select 'game_revisions' t, count(*) n, max(published_at)::text last, max(slate_date)::text max_slate from forge_game_revisions where slate_date >= '2026-11-01' union all select 'final_pregame', count(*), max(created_at)::text, null from forge_final_pregame_revisions where created_at > '2026-11-01' union all select 'update_queue', count(*), max(created_at)::text, null from forge_game_update_queue where created_at > '2026-11-01' union all select 'reserve_proj', count(*), max(created_at)::text, max(as_of_date)::text from forge_reserve_projections where as_of_date >= '2026-11-01' union all select 'board_releases', count(*), max(created_at)::text, null from forge_board_releases where created_at > '2026-11-01' union all select 'served_ledger', count(*), max(created_at)::text, null from forge_served_forecast_ledger where created_at > '2026-11-09'
